'  if (K < 6.5){ float sp = floor(fract(K + 0.001) * 10.0 + 0.5); vec3 q = p + w * 0.5; vec2 dw = vec2(cos(WA), sin(WA)); float hk = p.y; bool cal = sp > 0.5 && sp < 1.5, near = sp > 2.5;',   /* STORM FRONT (user 11-24: "wouldnt storms be wider? i dont feel like i ever see a single pillared storm cloud"; "we should draw storm fronts"): a line of cells SSW-NNE across the western horizon at different stages, bodies merging into a wall, ONE shared anvil fanning downwind, rain shafts under the mature cells. sp 0: the front ~60 km west; sp 2: the same amid fair-weather cumulus; sp 3: the front APPROACHING ~22 km, a shelf cloud along its leading edge; sp 1 calvus: one young storm, no anvil */
'    vec2 L0 = vec2(-4.0, near ? 30.0 : (cal ? 42.0 : 60.0)), ld = normalize(vec2(1.0, 0.22)), ln = vec2(-ld.y, ld.x), lp = p.xz - L0; float al = dot(lp, ld), sd = -dot(lp - ld * al, dw);',   /* al: km along the line; sd: km downwind of it (toward the viewer) */
