'      vec2 ck = cal ? (k == 0 ? L0 : L0 + ld * (h1 - 0.5) * 34.0 + ln * (h2 - 0.5) * 16.0) : L0 + ld * ((fk - 2.5) * 12.5 + (h1 - 0.5) * 11.0) + ln * (h2 - 0.5) * 12.0; float h4 = fract(h2 * 3.7 + 0.35), Rk = cal ? (k == 0 ? 5.5 : 2.4 + 2.0 * h3) : (h4 > 0.3 ? 7.0 + 3.0 * h3 : 3.5 + 3.0 * h3), Tk = cal ? (k == 0 ? 9.6 : 4.5 + 3.0 * h4) : (h4 > 0.3 ? 11.9 + 0.4 * h4 : mix(5.5, 9.0, h4 / 0.3));   /* most cells mature, broad, feeding the anvil; a few younger towers below it */   /* mature cells reach and feed the anvil; younger towers stay below it as domes */   /* uneven spacing, sizes and stages: no row of matching pillars */',
