'    float cu = 0.0; if (oct > 2 && ((sp > 1.5 && sp < 2.5) || cal)){ float hc = (p.y - 1.2) / 1.9; if (hc > 0.0 && hc < 1.0){ vec3 qq = p + w; float cel = nz(qq * vec3(0.085, 0.035, 0.085)), bc = nz((p + w * 0.5) * vec3(0.018, 0.01, 0.018)), lu = nz(qq * vec3(0.42)), ft = cel * 1.25 + bc * 0.35 - (cal ? 1.02 : 0.9) + (nzc(vec3(p.x * 0.009, 0.31, p.z * 0.011)) - 0.5) * 0.5;',
