'vec4 layer(vec3 rd, vec3 L, vec3 amb, float K, float B0, float B1, float cov, int N, float jit, out float tz){',
'  tz = 1e9; if (K < -0.5 || rd.y < 0.005) return vec4(0.0, 0.0, 0.0, 1.0); float hm = 0.5 * (B0 + B1); vec2 om = wInt(hm, true); gW = vec3(-om.x, 0.0, -om.y); gVm = wInt(hm, false); gDm = K > 5.5 ? wDrift(B0, hm, 45.0) : wDrift(B0, hm, 20.0); float lo = B0 - 0.3 * (B1 - B0), t0 = max(lo, 0.05) / rd.y, t1 = B1 / rd.y, len = min(t1 - t0, K > 7.5 ? 40.0 : (K > 5.5 && K < 6.5 ? 130.0 : 26.0)); int NN = K > 5.5 && K < 6.5 ? 64 : N; float dt = len / float(NN);',
'  float mu = dot(rd, L), T = 1.0; vec3 C = vec3(0.0); float sg = K > 8.5 ? 7.0 : K < 0.5 ? 13.0 : (K > 6.5 && K < 7.5) ? 22.0 : (K > 4.5 && K < 5.5) ? 20.0 : (K > 5.5 && K < 6.5) ? 16.0 : 12.0;',   /* Sc opaque water cloud; stratus thick enough to hide the sun disk */
'  float zw = 0.0, zs = 0.0; for (int i = 0; i < 64; i++){ if (i >= NN) break; float t = t0 + (float(i) + jit) * dt; vec3 p = rd * t; float d = dens(p, 5, K, B0, B1, cov); if (d < 0.003) continue;',
'    vec3 Lc = 3.0 * trans(vec3(0.0, RE, 0.0) + p, L);',
'    float sst = K > 7.5 && K < 8.5 ? 0.045 : (K < 0.5 ? 0.09 : (K < 1.5 ? 0.06 : (K > 5.5 && K < 6.5 ? 0.35 : 0.12))), sok = K > 7.5 && K < 8.5 ? mix(1.0, 1.5, smoothstep(0.05, 0.35, L.y)) : 1.0, od = 0.0; for (int j = 1; j <= 3; j++){ od += dens(p + L * (sst * float(j * j)), 2, K, B0, B1, cov); } od *= sok;',   /* Ac: short strong shadow steps, grey undersides */
'    vec3 ms = vec3(0.0); float aa = 1.0, bb = 1.0, cc = 1.0; for (int k = 0; k < 3; k++){ ms += aa * Lc * mix(hg(mu * cc, 0.6), hg(mu * cc, -0.25), 0.3) * exp(-od * 2.2 * bb); aa *= 0.55; bb *= 0.45; cc *= 0.6; }',
'    float hh = clamp((p.y - B0) / (B1 - B0), 0.0, 1.0), gk = K > 8.5 ? 0.4 : (K > 6.5 && K < 7.5 ? 0.22 * smoothstep(0.03, 0.3, L.y) : (K > 4.5 && K < 5.5 ? 0.1 : 1.0)); vec3 ag = (K > 6.5 && K < 7.5) || (K > 8.5 && K < 9.5) || K < 0.5 || (K > 4.5 && K < 5.5) ? mix(vec3(dot(amb, vec3(0.33))) * vec3(0.9, 0.95, 1.06), amb, mix(0.2, 0.55, smoothstep(0.02, 0.25, L.y))) : amb;   /* a sheet goes blue-grey at a blocked sunset, not brown */',
'    if (K > 5.5 && K < 6.5 && p.y < 9.8){ float spc = floor(fract(K + 0.001) * 10.0 + 0.5); bool cl2 = spc > 0.5 && spc < 1.5; vec2 L0c = vec2(-4.0, spc > 2.5 ? 30.0 : (cl2 ? 42.0 : 60.0)), ldc = normalize(vec2(1.0, 0.22)), dwc = vec2(cos(WA), sin(WA));',   /* UNDER THE STORM (user 11-24 recordings: "improve below the cumulonimbus"): the 3-step shadow march reaches ~3 km, never the anvil 8-12 km up, so everything under the base was lit as in sunshine (bright beige rain and scud). The storm footprint is geometry (the line of cells, the anvil fanning downwind): look up it toward the sun for direct light and straight up for skylight */
'      vec2 pb = (p + gW * 0.5).xz, ls = L.xz / max(L.y, 0.15), pd = pb + ls * (10.6 - p.y), pm = pb + ls * max(5.5 - p.y, 0.0), pu = pb; float ad = dot(pd - L0c, ldc), sdd = -dot(pd - L0c - ldc * ad, dwc), am = dot(pm - L0c, ldc), sdm = -dot(pm - L0c - ldc * am, dwc), au = dot(pu - L0c, ldc), sdu = -dot(pu - L0c - ldc * au, dwc);',   /* look up the sun path at the anvil height AND mid-tower: with the sun low beyond the front the path crosses the towers, not the anvil (the rain under the approaching front glowed) */
'      float cvd = cl2 ? smoothstep(9.0, 4.0, length(pd - L0c)) : max(smoothstep(40.0, 30.0, abs(ad)) * smoothstep(-12.0, -6.0, sdd) * smoothstep(30.0, 14.0, sdd), smoothstep(40.0, 30.0, abs(am)) * smoothstep(11.0, 6.0, abs(sdm))), cvu = cl2 ? smoothstep(9.0, 4.0, length(pu - L0c)) : smoothstep(40.0, 30.0, abs(au)) * smoothstep(-12.0, -6.0, sdu) * smoothstep(30.0, 14.0, sdu);',
'      float dep = smoothstep(2.8, 1.4, p.y); ms *= mix(1.0, 0.12, cvd * dep); ag *= mix(1.0, 0.55, cvu * dep); }',   /* only under the base (rain, scud, the base itself): applied to the whole tower it painted dark blotches on the sunlit faces */
'    ag += gHor * (K < 1.5 ? 0.55 : 0.35) * mix(1.0, 0.6, hh); ms += Lc * hg(mu, 0.86) * 0.55 * exp(-od * 1.8) * (1.0 - smoothstep(0.02, 0.3, d)) * smoothstep(-0.02, 0.06, L.y);',   /* SILVER LINING (user 11-24 "bright edges at sunset"): the thin edges of a cloud backlit by the sun glow in forward scatter */
'    float tone = 1.0; if (K > 6.5 && K < 7.5) tone = 0.5 + 1.0 * nz(rx(p + gW, 0.4) * vec3(0.09, 0.3, 0.2) + aoff(p)) * (0.6 + 0.4 * nz(rx(p, 1.1) * vec3(0.35, 0.5, 0.5)));',   /* stratus: soft darker and lighter patches */
