'    if (K > 8.5 && K < 9.5){ vec3 pt = p + gW; vec2 wd = vec2(cos(WA), sin(WA)); float fib = nz(rx(pt, WA - 0.05) * vec3(0.012, 0.15, 0.22) + aoff(p)), pat = nzc(pt * vec3(0.009, 0.05, 0.011) + 0.21), rol = sin(dot(pt.xz, vec2(-wd.y, wd.x)) * 3.4 + 4.0 * nz(pt * vec3(0.01, 0.1, 0.01))); tone = 0.86 + (pat - 0.5) * 0.42 + (fib - 0.5) * 0.16 + rol * 0.035; }',   /* altostratus: soft lighter and darker patches, a faint fibrous grain along the wind and very gentle rolls across it (the old high-contrast stripes fanned out from the horizon like brush strokes) */
