'vec2 ciBend(vec2 r, float zz){ return vec2(r.x, r.y + (nzc(vec3(r.x * 0.018, zz + 0.71, r.y * 0.012)) - 0.5) * 7.0 + (nz(vec3(r.x * 0.06, zz + 0.93, r.y * 0.04)) - 0.5) * 2.4 + (nz(vec3(r.x * 0.15, zz + 0.37, r.y * 0.1)) - 0.5) * 0.5); }',   /* fibres curve gently over 14-55 km (user 11-23: "too many straight lines", "lines a little too pronounced perfectly"); slow and broad, never the tight crossing warp that read as oil */
'float ciTex(vec2 r, float zz, float fa, float fb){ vec2 b = ciBend(r, zz); return 0.25 + 0.5 * mix(nz(vec3(b.x * 0.09, zz + 0.4, b.y * 1.1)), 0.5, fb) + 0.3 * mix(nz(vec3(b.x * 0.25, zz + 0.6, b.y * 2.7)), 0.5, fa); }',   /* along-fibre frequency up (0.05 -> 0.09, 0.13 -> 0.25): fibres break into segments of varied length, not endless ruled lines */   /* THE FIBRATUS FIBRE TEXTURE, shared: uncinus, intortus and vertebratus are built from it, not drawn (user 11-23: "you are so accurate on all others but these are hallucinating"; drawn strokes, cells and polylines read as illustration, the noise field reads as ice) */
'float ciBand(vec2 r, float zz, float th){ r = ciBend(r, zz); return smoothstep(th, th + 0.18, nz(vec3(r.x * 0.012, zz, r.y * 0.06)) * 0.75 + nz(vec3(r.x * 0.03, zz + 0.2, r.y * 0.16)) * 0.35 - 0.05); }',   /* the fibratus streak mask */
