'float ciHeadU(vec2 r, float zz, float cov){ float t0 = mix(0.75, 0.62, cov) - (nzc(vec3(r.x * 0.007, zz + 0.29, r.y * 0.011)) - 0.5) * 0.75 - (nz(vec3(r.x * 0.03, zz + 0.61, r.y * 0.04)) - 0.5) * 0.12;   /* strong clustering: groups with real gaps; perspective turns an even scatter into horizontal ranks */ return smoothstep(t0, t0 + 0.1, nzc(vec3(r.x * 0.07, zz + 0.13, r.y * 0.1)) * 0.8 + nz(vec3(r.x * 0.32, zz + 0.31, r.y * 0.4)) * 0.25); }',   /* uncinus crests: smaller and more numerous than the generic tuft, with clear sky between (the Arizona photo) */
'float ccGrain(vec2 q, float zz, float t, float th){ vec2 r = rot(q, WA + 0.5), r2 = rot(q, WA - 1.0); float pf = t * 0.0022, zg = zz + nz(vec3(q.x * 0.13, 0.47, q.y * 0.13)) * 0.5 + nz(vec3(q.x * 0.41, 0.91, q.y * 0.41)) * 0.2;',   /* CIRROCUMULUS GRAIN FROM THE APPROVED ALTOCUMULUS (user 11-23: Cc "really bad ... the texture pattern isnt realistic"): the same rounded puffs of two sizes in rafts, at Cc scale (~0.35 km, ~2 deg overhead: a little larger than the atlas <1 deg, so they read instead of speckling); grains narrower than a pixel fade into a soft veil */
'  vec2 r4 = rot(q, WA - 1.57), r5 = rot(q, WA + 1.58); float p1 = (nz(vec3(r.x * 0.7, zg + 0.7, r.y * 0.7)) + nz(vec3(r4.x * 0.66, zg + 0.17, r4.y * 0.66))) * 0.5, p2 = (nz(vec3(r2.x * 1.15, zg + 0.35, r2.y * 1.15)) + nz(vec3(r5.x * 1.2, zg + 0.83, r5.y * 1.2))) * 0.5,   /* each grain field is two value-noise copies at different angles averaged: the blocky axis-aligned features of one copy cancel, the grains come out round */ pz = mix(p1, p2, smoothstep(0.25, 0.75, nzc(vec3(q.x * 0.03, zz + 0.65, q.y * 0.03)))), raft = nzc(vec3(r.x * 0.05, zz + 0.4, r.y * 0.07)), p3 = (nz(vec3(r.x * 0.42, zg + 0.55, r.y * 0.42)) + nz(vec3(r4.x * 0.4, zg + 0.05, r4.y * 0.4))) * 0.5; pz = mix(pz, p3, smoothstep(0.5, 0.8, nzc(vec3(q.x * 0.022, zz + 0.95, q.y * 0.022))));   /* VARIETY (user 11-23: "the pattern is too uniform"): larger merged clumps in some regions, fine grains in others */',
'  float m2 = (nz(vec3(r.x * 0.16, zg + 0.27, r.y * 0.16)) + nz(vec3(r2.x * 0.15, zg + 0.61, r2.y * 0.15))) * 0.5, c = (pz - 0.5) * 1.35 + 0.5 + (raft - 0.5) * 0.55 + (m2 - 0.5) * 0.45 + 0.04, sw = 0.17 + pf * 0.8;   /* clumps a few grains across: grains join into clusters and chains, a network not confetti; softer rims (user 11-23: "this area still feels a bit uniform") */ return mix(smoothstep(th - 0.2 - sw * 0.5, th - 0.2 + sw * 0.5, c), 0.45, smoothstep(0.08, 0.2, pf)); }',
